from typing import Generic, TypeVar
from pydantic import BaseModel

T = TypeVar("T")

class Page(BaseModel, Generic[T]):
    items: list[T]
    total: int
    page: int
    size: int
    pages: int

    @classmethod
    def of(cls, rows: list, total: int, pg) -> "Page[T]":
        return cls(items=rows, total=total, page=pg.page, size=pg.size,
                   pages=max(1, -(-total // pg.size)))     # 向上取整的小技巧

