from pydantic_settings import BaseSettings, SettingsConfigDict   # pip install pydantic-settings

class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8",
                                      extra="ignore", case_sensitive=False)

    app_name: str = "task-service"
    env: str = Field("dev", pattern="^(dev|staging|prod)$")
    debug: bool = False
    api_prefix: str = "/api/v1"

    database_url: str = "sqlite+aiosqlite:///./dev.db"
    db_pool_size: int = 10
    redis_url: str = "redis://localhost:6379/0"

    secret_key: str = Field(min_length=32)      # 不给默认值 -> 忘配就启动失败（好事）
    access_token_expire_minutes: int = 30

    cors_origins: list[str] = ["http://localhost:5173"]

    @computed_field
    @property
    def is_prod(self) -> bool:
        return self.env == "prod"

@lru_cache            # 关键：全进程只解析一次 .env，注入依赖时零开销
def get_settings() -> Settings:
    return Settings()

from sqlalchemy import Select, func, select
from sqlalchemy.ext.asyncio import AsyncSession

from app.db.models.task import Task

class TaskRepo:
    def __init__(self, db: AsyncSession):
        self.db = db

    def _visible(self) -> Select:                    # 软删除过滤统一收口
        return select(Task).where(Task.deleted_at.is_(None))

    def _apply(self, stmt: Select, f: TaskFilter) -> Select:
        if f.done is not None:
            stmt = stmt.where(Task.done.is_(f.done))
        if f.owner_id:
            stmt = stmt.where(Task.owner_id == f.owner_id)
        if f.min_priority is not None:
            stmt = stmt.where(Task.priority >= f.min_priority)
        return stmt

    async def page(self, f: TaskFilter, skip: int, limit: int) -> tuple[list[Task], int]:
        stmt = self._apply(self._visible(), f)
        total = await self.db.scalar(
            select(func.count()).select_from(stmt.order_by(None).subquery())
        )
        rows = await self.db.scalars(
            stmt.order_by(Task.priority, Task.created_at.desc()).offset(skip).limit(limit)
        )
        return list(rows), total or 0

    async def get_for_owner(self, tid: int, uid: int) -> Task | None:
        return await self.db.scalar(self._visible().where(Task.id == tid, Task.owner_id == uid))

    async def create(self, **data) -> Task:
        task = Task(**data)
        self.db.add(task)
        await self.db.flush()          # flush 拿到自增 id，但事务仍未结束
        return task

# ---- core/exceptions.py：领域异常，与 HTTP 解耦 ----
class BusinessError(Exception):
    def __init__(self, code: str, message: str, status_code: int = 400):
        self.code, self.message, self.status_code = code, message, status_code
        super().__init__(message)

class NotFound(BusinessError):
    def __init__(self, code: str, message: str):
        super().__init__(code, message, status_code=404)

# ---- services/task.py ----
class TaskService:
    MAX_ACTIVE = 200

    def __init__(self, repo: TaskRepo):
        self.repo = repo

    async def create(self, *, user: User, payload: TaskCreate) -> Task:
        _, active = await self.repo.page(TaskFilter(owner_id=user.id, done=False), 0, 1)
        if active >= self.MAX_ACTIVE:
            raise BusinessError("TASK_LIMIT_EXCEEDED", "active task limit is 200")
        return await self.repo.create(**payload.model_dump(), owner_id=user.id)

    async def finish(self, tid: int, user: User) -> Task:
        task = await self.repo.get_for_owner(tid, user.id)
        if task is None:
            raise NotFound("TASK_NOT_FOUND", f"task {tid} not found")
        task.done = True
        return task

