from app.core.config import get_settings

password_hash = PasswordHash((BcryptHasher(),))
settings = get_settings()

def hash_password(plain: str) -> str:
    return password_hash.hash(plain)

def verify_password(plain: str, hashed: str) -> bool:
    return password_hash.verify(plain, hashed)

def create_access_token(subject: int, roles: list[str]) -> str:
    now = datetime.now(UTC)
    payload = {
        "sub": str(subject),
        "roles": roles,
        "iat": now,
        "exp": now + timedelta(minutes=settings.access_token_expire_minutes),  # 必须写
        "jti": uuid4().hex,                 # 用于吊销 / 审计
    }
    return jwt.encode(payload, settings.secret_key, algorithm="HS256")

def decode_token(token: str) -> dict:
    try:
        return jwt.decode(token, settings.secret_key, algorithms=["HS256"])   # 自动校验 exp
    except jwt.ExpiredSignatureError:
        raise BusinessError("TOKEN_EXPIRED", "login expired", status_code=401)
    except jwt.InvalidTokenError:
        raise BusinessError("TOKEN_INVALID", "invalid token", status_code=401)

