import json, logging, sys
from app.core.middleware import request_id

class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload = {
            "ts": self.formatTime(record, "%Y-%m-%dT%H:%M:%S%z"),
            "level": record.levelname,
            "logger": record.name,
            "rid": request_id.get(),
            "msg": record.getMessage(),
        }
        for k in ("path", "cost_ms", "status", "uid"):
            if hasattr(record, k):
                payload[k] = getattr(record, k)
        return json.dumps(payload, ensure_ascii=False, default=str)

def setup_logging(debug: bool = False) -> None:
    h = logging.StreamHandler(sys.stdout)        # 容器里日志走 stdout，交给平台收集
    h.setFormatter(JsonFormatter())
    root = logging.getLogger()
    root.handlers = [h]
    root.setLevel(logging.DEBUG if debug else logging.INFO)

import logging
from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from sqlalchemy.exc import IntegrityError

from app.core.exceptions import BusinessError
from app.core.middleware import request_id

def register_handlers(app: FastAPI) -> None:

    @app.exception_handler(BusinessError)
    async def business_error(_: Request, exc: BusinessError):
        return JSONResponse(status_code=exc.status_code,
                            content={"ok": False, "code": exc.code, "message": exc.message,
                                     "trace_id": request_id.get()})

    @app.exception_handler(RequestValidationError)
    async def validation_error(_: Request, exc: RequestValidationError):
        # 把 FastAPI 默认的 422 结构翻译成前端友好的形式
        fields: dict[str, list[str]] = {}
        for e in exc.errors():
            loc = ".".join(str(p) for p in e["loc"][1:]) or "body"
            fields.setdefault(loc, []).append(e["msg"])
        return JSONResponse(status_code=422,
                            content={"ok": False, "code": "VALIDATION_ERROR",
                                     "message": "invalid parameters", "fields": fields})

    @app.exception_handler(IntegrityError)
    async def integrity_error(_: Request, exc: IntegrityError):
        return JSONResponse(status_code=409,
                            content={"ok": False, "code": "CONFLICT", "message": "data conflict"})

    @app.exception_handler(Exception)          # 兜底：不泄漏堆栈给客户端，但一定记日志
    async def unknown(_: Request, exc: Exception):
        logging.getLogger("app").exception("unhandled")
        return JSONResponse(status_code=500,
                            content={"ok": False, "code": "INTERNAL",
                                     "message": "server error", "trace_id": request_id.get()})
